let inPath = arg("--in")!
let outPath = arg("--out")!
let soundType = Float(arg("--type") ?? "1")!
let mix = Float(arg("--mix") ?? "100")!
let block = Int(arg("--block") ?? "4096")!
let maxFrames = Int(arg("--maxframes") ?? "4096")!
let raw = flag("--raw")
let repeats = Int(arg("--repeat") ?? "1")!

